def main():
    root = Path(__file__).resolve().parent / "MiniCraft-II-v0.1.1.SC2Mod"
    if root.exists():
        raise SystemExit("Output already exists. Rename it before rebuilding; no files overwritten.")
    payload = {path: base64.b64decode(value, validate=True) for path, value in METADATA.items()}
    for name, xml in CATALOGS.items():
        ET.fromstring(xml)
        payload["Base.SC2Data/GameData/" + name + ".xml"] = xml.encode("utf-8")
    includes = '<?xml version="1.0" encoding="utf-8"?>\n<Includes>\n' + ''.join('    <Catalog path="GameData/' + name + '.xml"/>\n' for name in CATALOGS) + '</Includes>\n'
    ET.fromstring(includes)
    payload["Base.SC2Data/GameData.xml"] = includes.encode("utf-8")
    for path, data in payload.items():
        dest = root / path
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_bytes(data)
    print("Created:", root)
    print("Open ComponentList.SC2Components in Galaxy Editor; Save As a new SC2Mod.")
    print("Experimental; native editor and game not verified.")
    archive = root.parent / "MiniCraft-II-v0.1.1-components.zip"
    if not archive.exists():
        with zipfile.ZipFile(archive, "x", zipfile.ZIP_DEFLATED) as z:
            for path, data in payload.items():
                z.writestr(root.name + "/" + path, data)
        with zipfile.ZipFile(archive) as z:
            if z.testzip() is not None:
                raise RuntimeError("Archive verification failed")
        print("ZIP:", archive)
if __name__ == "__main__":
    main()
